from pathlib import Path
import shutil, hashlib, json
from datetime import datetime, timezone

root = Path.cwd()
d = root / '.local/numeric-tail-20261004'
def read(p):
    data = p.read_bytes()
    return json.loads(data.decode('utf16' if data.startswith(b'\xff\xfe') else 'utf-8-sig'))
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
assert read(d / 'audit-results.json')['status'] == 'passed'
assert all(read(d / name)['status'] == 'passed' for name in ('ordinary-results.json', 'math-results-both.json', 'benchmark-results.json'))
out = d / ('superseded-first-recovery-' + datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S'))
out.mkdir(exist_ok=False)
files = {}
def copy(src, relative):
    dest = out / relative
    dest.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dest)
    assert sha(src) == sha(dest)
    files[str(src)] = {'archive': str(dest), 'sha256': sha(dest)}
for p in d.iterdir():
    if p.is_file() and p.suffix in ('.py', '.ps1', '.sh', '.rs', '.json', '.log', '.exit', '.stderr', '.stdout', '.cjs') and not p.name.startswith(('before-', 'origin-', 'identity-')):
        copy(p, Path(p.name))
for name in ('source.tar', 'identity-heap-after.json', 'identity-differential-after.json', 'heap-after.exe', 'differential-after.exe'):
    copy(d / name, Path(name))
libraries = read(d / 'identity-heap-after.json')['libraryHashes']
assert libraries == read(d / 'identity-differential-after.json')['libraryHashes']
for relative, expected in libraries.items():
    p = root / relative
    assert sha(p) == expected
    copy(p, Path('libraries') / Path(relative).relative_to('target/release'))
for p in (d / 'wasm-bindings').iterdir():
    if p.is_file(): copy(p, Path('wasm-bindings') / p.name)
copy(root / 'target/wasm32-unknown-unknown/debug/pine_wasm.wasm', Path('compiled-input.wasm'))
receipt = {
    'status': 'archived',
    'purpose': 'Fully audited initial numerical recovery; constant extreme recovery performed unnecessary scans. Superseded by O(1) existing constant proof.',
    'directory': str(out), 'files': files,
    'freshNativeProbeProcesses': 724, 'priorOrdinaryRawReceiptsCompared': 412,
    'counts': {'ordinary': 412, 'math': 132, 'benchmark': 180, 'realWasmNodeProcesses': 1, 'realWasmCases': 3},
    'rawReceiptDirectoriesRemainImmutableAtTheirOriginalLocations': True,
    'rawSummaryLocators': {name: str(out / name) for name in ('ordinary-results.json', 'math-results-both.json', 'benchmark-results.json', 'audit-results.json')},
}
(out / 'archive-identity.json').write_text(json.dumps(receipt, indent=2, ensure_ascii=False), encoding='utf8')
(d / 'superseded-first-recovery.json').write_text(json.dumps(receipt, indent=2, ensure_ascii=False), encoding='utf8')
print('Preserved audited initial recovery in', out)

