"""Read-only independent receipt audit. Never starts a build or a probe.

The after numerical oracle is independently implemented here from exact input
float Fractions. Diagnostics stay diagnostics, and every raw record contributes
to the audit. Use --partial only to inspect data while the root is collecting it.
"""
from __future__ import annotations
import argparse
from collections import Counter
from datetime import datetime, timezone
from fractions import Fraction
import hashlib
import json
import math
from pathlib import Path
import re
import statistics
import struct
import tarfile

D = Path(__file__).resolve().parent
ROOT = D.parents[1]
BASE = 'f4e687035135642bf32e810b2538bdca14898852'
DIAGNOSTICS = {'unqualified_mixed_scale_2', 'unqualified_third_component_5'}

def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def text(path):
    raw = Path(path).read_bytes()
    return raw.decode('utf16') if raw.startswith((b'\xff\xfe', b'\xfe\xff')) else raw.decode('utf-8-sig')

def load(path):
    return json.loads(text(path), parse_constant=lambda v: (_ for _ in ()).throw(ValueError('Nonfinite JSON '+v)))

def check(condition, explanation):
    if not condition:
        raise AssertionError(explanation)

def frozen_sources(tag):
    manifest = D / (tag+'-source-identity.json')
    identity = load(manifest)
    archive = D / ('before-source.tar' if tag == 'before' else 'source.tar')
    expected_count = 6308 if tag == 'before' else 6310
    check(identity['base_commit'] == BASE, tag+' base commit')
    files = identity['files']
    check(len(files) == expected_count, tag+' file count')
    with tarfile.open(archive) as tar:
        entries = {m.name: m for m in tar.getmembers() if m.isfile()}
        check(len(entries) == expected_count and set(entries) == set(files), tag+' tar paths')
        for name, expected in files.items():
            check(not Path(name).is_absolute() and '..' not in Path(name).parts, 'Unsafe tar path '+name)
            check(hashlib.sha256(tar.extractfile(entries[name]).read()).hexdigest() == expected, tag+' tar hash '+name)
            if tag == 'after':
                check(sha(ROOT/name) == expected, 'Current after source changed '+name)
    if tag == 'after':
        check(sha(D/'source-identity.json') == sha(manifest), 'After source locator changed')
    return {'files':expected_count, 'manifestSha256':sha(manifest), 'archiveSha256':sha(archive), 'baseCommit':BASE}

def probe_identities():
    baseline = load(D/'before-binary-identity.json')
    check(len(baseline['libraries']) == 4 and set(baseline['probes']) == {'heap','dispatch','result','differential'}, 'Baseline scope is not 4 libraries / 4 probes')
    check(baseline['sourceIdentitySha256'] == sha(D/'before-source-identity.json'), 'Before manifest archival identity')
    check(baseline['sourceArchiveSha256'] == sha(D/'before-source.tar'), 'Before tar archival identity')
    for name, row in baseline['libraries'].items():
        check(sha(row['archive']) == row['sha256'], 'Baseline library archive '+name)
    result = {}
    for tag, probes in [('before',('heap','dispatch','result','differential')), ('after',('heap','differential'))]:
        for probe in probes:
            receipt_path = D/f'identity-{probe}-{tag}.json'
            receipt = load(receipt_path)
            binary = D/f'{probe}-{tag}.exe'
            source = D/('differential.rs' if probe == 'differential' else probe+'_probe.rs')
            check(receipt['tag'] == tag and receipt['probe'] == probe, 'Probe role '+probe+'/'+tag)
            check(sha(binary) == receipt['executableSha256'] and sha(source) == receipt['sourceSha256'], 'Probe binary/source hash '+probe+'/'+tag)
            args = receipt['compilerArguments']
            for required in ('-O','lto=thin','codegen-units=1','--edition=2024'):
                check(required in args, 'Compiler flag '+required)
            if probe in ('differential','result'):
                check(any(args[i:i+2] == ['--cfg','borrowed_result'] for i in range(len(args)-1)), 'Owned/view assertions missing')
            check(len(receipt['libraryHashes']) == 4, 'Linked library identity count')
            if tag == 'before':
                archive = baseline['probes'][probe]
                origin_path = D/f'origin-{probe}-link.json'
                origin = load(origin_path)
                check(sha(receipt_path) == archive['adaptedLinkSha256'] and sha(origin_path) == archive['originLinkSha256'], 'Inherited link receipt hash')
                check(receipt['originSha256'] == sha(origin_path) and sha(receipt['origin']) == sha(origin_path), 'Inherited original link identity')
                for field in ('compilerArguments','libraryHashes','executableSha256','sourceSha256','rustc','probe'):
                    check(receipt[field] == origin[field], 'Adapted baseline changed '+field)
                check(archive['binarySha256'] == sha(binary) and archive['sourceSha256'] == sha(source), 'Archival baseline probe identity')
                for name, expected in receipt['libraryHashes'].items():
                    check(baseline['libraries'][name]['sha256'] == expected, 'Inherited library mismatch '+name)
            else:
                for name, expected in receipt['libraryHashes'].items():
                    check(sha(ROOT/name) == expected, 'Current after linked library '+name)
            result[probe+'-'+tag] = {'binary':str(binary), 'binarySha256':sha(binary), 'source':str(source), 'sourceSha256':sha(source), 'linkReceipt':str(receipt_path), 'linkReceiptSha256':sha(receipt_path), 'link':receipt}
    return result

def snapshot_lines(raw):
    lines = raw.splitlines()
    check(len(lines) == 33 and all(lines), 'Expected 33 differential lines')
    records = [json.loads(line, parse_constant=lambda v: (_ for _ in ()).throw(ValueError(v))) for line in lines]
    for i,row in enumerate(records):
        check(set(row) == {'snapshot','changes'} and isinstance(row['snapshot'],dict), 'Malformed differential envelope')
        check(row['changes'] is None if i == 0 else isinstance(row['changes'],dict), 'Malformed changes envelope')
    return records

def run_receipt(row, command):
    check(row['command'] == command and row['returncode'] == 0, 'Raw process command/exit')
    exit_record = load(row['exit'])
    check(exit_record == {'command':command, 'returncode':0, 'timeoutSeconds':None}, 'Exit receipt contents')
    for name in ('stdout','stderr','exit'):
        check(sha(row[name]) == row[name+'Sha256'], 'Raw receipt hash '+name)
    check(math.isfinite(row['wallSeconds']) and row['wallSeconds'] >= 0, 'Invalid wall seconds')
    return Path(row['stdout']).read_bytes()

def result_locator(name):
    path = D/name
    data = load(path)
    prefix = {'ordinary-results.json':'ordinary','math-results-both.json':'math','benchmark-results.json':'benchmark'}[name]
    matches = [p for p in (D/(prefix+'-receipts')).glob('*/summary.json') if sha(p) == sha(path)]
    check(len(matches) == 1, 'Ambiguous immutable summary '+name)
    return data,matches[0]

def ordinary(identities):
    data, immutable = result_locator('ordinary-results.json')
    plan = load(D/'ordinary-plan.json')
    check(data['status'] == 'passed' and len(data['records']) == 412 and data['plannedCases'] == 412 and data['plannedFreshProcesses'] == 412, 'Ordinary counts/status')
    check(sha(D/'ordinary_parity.py') == data['runnerSha256'], 'Ordinary runner changed')
    for tag in ('before','after'):
        check(data['identities'][tag] == identities['differential-'+tag], 'Ordinary differential identity '+tag)
    prior = load(data['priorSummary'])
    check(sha(data['priorSummary']) == data['priorSummarySha256'] == plan['priorSummarySha256'], 'Prior ordinary immutable SHA')
    master = ROOT/'.local/statistics-qr-20261004/differential-results.json'
    check(sha(master) == data['masterSha256'] == sha(data['priorSummary']), 'Prior ordinary master SHA')
    check(identities['differential-before']['binarySha256'] == prior['identities']['after']['binarySha256'], 'Inherited prior after binary identity')
    keys = lambda rows: [(r['source'],r['mode'],r['seedBars']) for r in rows]
    check(keys(data['records']) == keys(plan['cases']) == keys(prior['records']) and len(set(keys(data['records']))) == 412, 'Ordinary exact ordered case plan')
    equal = snapshots = changes = 0
    for old,row in zip(prior['records'],data['records']):
        check(row['sourceSha256'] == old['sourceSha256'] == sha(ROOT/row['source']), 'Ordinary source identity')
        command = [identities['differential-after']['binary'],str(ROOT/row['source']),row['mode'],str(row['seedBars'])]
        raw = run_receipt(row['after'],command)
        frames = snapshot_lines(raw)
        path = Path(data['priorSummary']).parent/old['results']['after']['stdoutReceipt']
        check(sha(path) == old['results']['after']['stdoutSha256'] == row['priorStdoutSha256'] and str(path) == row['priorStdout'], 'Prior raw ordinary SHA/path')
        check(raw == path.read_bytes() and row['equal'] is True and row['snapshots'] == 33 and row['changes'] == 32, 'Ordinary byte mismatch')
        equal += 1; snapshots += len(frames); changes += len(frames)-1
    check(data['completedCases'] == data['passed'] == equal == 412 and data['failures'] == [], 'Ordinary final qualification')
    check(data['equalSnapshots'] == snapshots == 13596 and data['equalChanges'] == changes == 13184, 'Ordinary snapshot/changes total')
    return {'status':'passed','freshProcesses':412,'priorRawComparisons':412,'snapshots':snapshots,'changes':changes,'immutableSummary':str(immutable),'summarySha256':sha(immutable)}

def float_or_na(value):
    check(value is None or (not isinstance(value,bool) and isinstance(value,(int,float)) and math.isfinite(value)), 'Finite float / NA expected')
    return None if value is None else float(value)

def rounded(value):
    try: number = float(value)
    except OverflowError: return None
    return number if math.isfinite(number) else None

def exact_wma(values):
    if not values or None in values: return None
    if all(value == values[0] for value in values): return values[0]
    exact = sum((Fraction(value)*weight for weight,value in enumerate(values,1)), Fraction())
    return rounded(exact/Fraction(len(values)*(len(values)+1),2))

def math_input(spec,index,close):
    length = spec['length']
    if spec['kind'] in ('paired','identity','inverse'):
        x = spec['offset'] + index%length
        y = spec['rightOffset'] + (index*2)%length if spec['kind'] == 'paired' else (-x if spec['kind'] == 'inverse' else x)
        return {'x':float(x),'y':float(y)}
    pattern = spec['pattern']
    if pattern == 'constant': x = spec['value']
    elif pattern == 'cancellation': x = (1e308,1e308,-1e308,1.0)[index%4]
    elif pattern == 'tail': x = 1e308 if index < 2 else 1.0
    elif pattern == 'na-tail': x = 1e308 if index < 2 else (None if index == 2 else 1.0)
    elif pattern == 'forming': x = 1e308 if close > 100.5 else -1e308
    elif pattern == 'stage-overflow': x = (-1e308,1.5e308)[index%2]
    elif pattern == 'mixed-scale': x = (1e308,1e-308)[index%2]
    elif pattern == 'third-component': x = (1e308,1e308,2.0**923,1.0,-1e308)[index%5]
    else: raise ValueError('Unknown pattern '+pattern)
    return {'x':x}

def math_expected(spec,index,samples,cache):
    length = spec['length']; smooth = round(math.sqrt(length))
    first = max(0,index-length-smooth+2)
    dynamic = tuple(row['x'] for row in samples[first:index+1]) if spec.get('pattern') == 'forming' else ()
    key = (spec['name'],index,dynamic)
    if key in cache: return cache[key]
    if spec['kind'] != 'weighted':
        result = {'corr':None,'cov':None}
        if index+1 >= length:
            window = samples[index-length+1:index+1]
            xs = [Fraction(row['x']) for row in window]; ys = [Fraction(row['y']) for row in window]
            # Exact raw moment algebra is safe for arbitrary rational values.
            sx,sy = sum(xs),sum(ys)
            cov = (sum(x*y for x,y in zip(xs,ys))-sx*sy/length)/length
            vx = (sum(x*x for x in xs)-sx*sx/length)/length
            vy = (sum(y*y for y in ys)-sy*sy/length)/length
            result['cov'] = rounded(cov)
            if vx and vy:
                result['corr'] = math.copysign(math.sqrt(float(cov*cov/(vx*vy))),float(cov))
    else:
        result = {'wma':None,'hma':None}
        if index+1 >= length:
            result['wma'] = exact_wma([row['x'] for row in samples[index-length+1:index+1]])
        if index+1 >= length+smooth-1:
            diff = []
            for end in range(index-smooth+1,index+1):
                window = [row['x'] for row in samples[end-length+1:end+1]]
                full,half = exact_wma(window),exact_wma(window[-max(1,length//2):])
                diff.append(None if full is None or half is None else rounded(2*Fraction(half)-Fraction(full)))
            result['hma'] = exact_wma(diff)
    cache[key] = result
    return result

def analyze_math(spec,mode,raw,cache):
    frames = snapshot_lines(raw); seed = spec['seed']
    confirmed = [100.0+(i%17)/16.0+.25 for i in range(seed)]
    counts = Counter(); failures = []
    for frame_index,frame in enumerate(frames):
        if frame_index == 0: closes = list(confirmed)
        else:
            current = seed+(frame_index-1)//4
            closes = confirmed+[100.0+(current%17)/16.0+(.5,-.5,.25,-.25)[(frame_index-1)%4]]
        samples = [math_input(spec,i,close) for i,close in enumerate(closes)]
        plots = frame['snapshot']['plots']; values = {p['title']:p['values'] for p in plots}
        titles = {'x','wma','hma'} if spec['kind'] == 'weighted' else {'x','y','corr','cov'}
        check(len(values) == len(plots) and set(values) == titles, 'Math plot titles')
        count = len(next(iter(values.values())))
        expected_count = len(closes) if mode == 'unlimited' else (min(seed,16) if frame_index == 0 else (min(len(closes)-1,16)+1 if (frame_index-1)%4 < 3 else min(len(closes),16)))
        check(count == expected_count and all(len(v) == count for v in values.values()), 'Math retention plot shape')
        for j in range(count):
            index = len(closes)-count+j
            for name,value in samples[index].items():
                check(float_or_na(values[name][j]) == value, 'Declared math source differs at '+str(index)+'/'+name)
            expected = math_expected(spec,index,samples,cache)
            for name,value in expected.items():
                actual = float_or_na(values[name][j]); counts['checked'] += 1
                counts['actualNa'] += actual is None; counts['expectedNa'] += value is None
                matched = actual is None if value is None else (actual is not None and abs(actual-value) <= max(abs(value)*2e-12,8*math.ulp(value)))
                if spec.get('constantExact') and value is not None:
                    matched = actual is not None and struct.pack('>d',actual) == struct.pack('>d',spec['value']); counts['exact'] += 1
                if not matched:
                    counts['mismatch'] += 1
                    if len(failures) < 24: failures.append({'snapshotIndex':frame_index,'barIndex':index,'plot':name,'actual':actual,'independentExpected':value})
        if frame_index > 0 and (frame_index-1)%4 == 3: confirmed = closes
    return {'checkedAggregateValues':counts['checked'],'mismatchValues':counts['mismatch'],'exactConstantValues':counts['exact'],
            'firstMismatches':failures,'actualNaAggregateValues':counts['actualNa'],'expectedNaAggregateValues':counts['expectedNa'],
            'independentMathPassed':counts['mismatch'] == 0 and not spec.get('unqualified'),'unqualifiedReason':spec.get('unqualified'),'snapshots':33,'changes':32}

def mathematics(identities):
    data,immutable = result_locator('math-results-both.json'); plan = load(D/'math-plan.json')
    check(data['status'] == 'passed' and len(data['records']) == data['plannedProcesses'] == data['completedProcesses'] == 132, 'Math counts/status')
    check(data['specs'] == plan['specs'] and data['sources'] == plan['sources'] and len(data['specs']) == 33, 'Math exact source plan')
    check(plan['publicCases'] == 66 and plan['plannedProcessesBothVersions'] == 132 and plan['qualifiedPublicCases'] == 62 and plan['unqualifiedPublicCases'] == 4, 'Math plan counts')
    specs = {s['name']:s for s in data['specs']}
    check({s['name'] for s in specs.values() if s.get('unqualified')} == DIAGNOSTICS, 'Qualification changed')
    for entry in data['sources'].values(): check(sha(entry['path']) == entry['sha256'], 'Math input SHA')
    check(sha(D/'independent_math.py') == data['runnerSha256'] and sha(D/'evidence_common.py') == data['commonSha256'], 'Math runner/common SHA')
    for tag in ('before','after'): check(data['identities'][tag] == identities['differential-'+tag], 'Math differential identity')
    expected_keys = {(name,mode,tag) for name in specs for mode in ('unlimited','retained') for tag in ('before','after')}
    actual_keys = [(r['case'],r['mode'],r['tag']) for r in data['records']]
    check(len(set(actual_keys)) == 132 and set(actual_keys) == expected_keys, 'Math duplicate/missing process')
    qualified = Counter(); passed = Counter(); diagnostic = Counter(); checked = Counter(); mismatches = Counter(); cache = {}
    qualified_checked = Counter(); diagnostic_checked = Counter(); qualified_mismatches = Counter(); diagnostic_mismatches = Counter()
    record_audit = []
    for row in data['records']:
        spec = specs[row['case']]; tag = row['tag']
        command = [identities['differential-'+tag]['binary'],data['sources'][row['case']]['path'],row['mode'],str(spec['seed'])]
        check(row['seedBars'] == spec['seed'], 'Math seed count')
        raw = run_receipt(row['run'],command)
        result = analyze_math(spec,row['mode'],raw,cache)
        check(result == row['analysis'], 'Independent math analysis disagreement '+str((row['case'],row['mode'],tag)))
        qualified[tag] += not spec.get('unqualified'); diagnostic[tag] += bool(spec.get('unqualified'))
        passed[tag] += result['independentMathPassed']; checked[tag] += result['checkedAggregateValues']; mismatches[tag] += result['mismatchValues']
        if spec.get('unqualified'):
            diagnostic_checked[tag] += result['checkedAggregateValues']; diagnostic_mismatches[tag] += result['mismatchValues']
        else:
            qualified_checked[tag] += result['checkedAggregateValues']; qualified_mismatches[tag] += result['mismatchValues']
        record_audit.append({'case':row['case'],'mode':row['mode'],'tag':tag,'qualified':not bool(spec.get('unqualified')),'checked':result['checkedAggregateValues'],'mismatch':result['mismatchValues']})
    check(dict(qualified) == data['qualifiedProcesses'] == {'before':62,'after':62}, 'Qualified process counts')
    check(dict(passed) == data['mathPassedProcesses'] and passed['after'] == 62, 'Math passed process counts')
    check(dict(diagnostic) == {'before':4,'after':4} and data['unqualifiedProcesses'] == 8, 'Diagnostic counts')
    check(data['failedAfterProcesses'] == 0 and data['afterMathFailures'] == [], 'Math final failures')
    return {'status':'passed','sources':33,'publicCases':66,'freshProcesses':132,'qualifiedProcesses':dict(qualified),'diagnosticProcesses':dict(diagnostic),
            'mathPassedProcesses':dict(passed),'checkedValues':dict(checked),'qualifiedCheckedValues':dict(qualified_checked),'diagnosticCheckedValues':dict(diagnostic_checked),
            'qualifiedMismatchValues':dict(qualified_mismatches),'diagnosticMismatchValues':dict(diagnostic_mismatches),'allMismatchValuesIncludingDiagnostics':dict(mismatches),
            'records':record_audit,'immutableSummary':str(immutable),'summarySha256':sha(immutable)}

def benchmark(identities):
    data,immutable = result_locator('benchmark-results.json'); plan = load(D/'benchmark-plan.json')
    check(data['status'] == 'passed' and len(data['records']) == data['plannedProcesses'] == data['completedProcesses'] == 180, 'Benchmark counts/status')
    check(data['cases'] == plan['cases'] and data['sources'] == plan['sources'] and len(data['cases']) == 30, 'Benchmark exact source plan')
    check(sha(D/'focused_benchmark.py') == data['runnerSha256'] and sha(D/'evidence_common.py') == data['commonSha256'], 'Benchmark runner/common SHA')
    for entry in data['sources'].values(): check(sha(entry['path']) == entry['sha256'], 'Benchmark input SHA')
    for tag in ('before','after'): check(data['identities'][tag] == identities['heap-'+tag], 'Benchmark heap identity')
    for tag in ('windows','linux'):
        quiet = data['quiescence']['gates'][tag]
        check(quiet['exitSha256'] == sha(D/f'gate-{tag}.exit') and quiet['logSha256'] == sha(D/f'gate-{tag}.log'), 'Timing gate receipt SHA')
    check(data['quiescence']['ourCompilationValidationAndCorrectnessProcessesFinished'] is True and data['quiescence']['matchingWindowsCompilerProcesses'] == [], 'Timing quiescence flags')
    cases = {c['name']:c for c in data['cases']}
    keys = [(r['case'],r['tag'],r['repetition']) for r in data['records']]
    check(len(set(keys)) == 180 and set(keys) == {(name,tag,repetition) for name in cases for tag in ('before','after') for repetition in range(3)}, 'Benchmark duplicate/missing processes')
    expected_order = [(c['name'],tag,rep) for rep in range(3) for c in data['cases'] for tag in (('before','after') if rep%2 == 0 else ('after','before'))]
    check(keys == expected_order, 'Benchmark alternating process order')
    rows = {}
    for row in data['records']:
        case = cases[row['case']]
        command = [identities['heap-'+row['tag']]['binary'],data['sources'][case['script']]['path'],str(case['bars']),case['mode']]
        raw = run_receipt(row['run'],command); lines = raw.splitlines()
        check(len(lines) == 1, 'Heap output line count')
        metrics = json.loads(lines[0]); check(metrics == row['metrics'], 'Heap parsed metrics differ')
        check(metrics['bars'] == case['bars'] and metrics['mode'] == case['mode'], 'Heap output mode / bars')
        for name,value in metrics.items():
            if isinstance(value,(int,float)) and not isinstance(value,bool): check(math.isfinite(value) and value >= 0, 'Heap nonfinite/negative '+name)
        rows.setdefault((row['case'],row['tag']),[]).append(metrics)
    summary = {}; metric_count = 0
    for case in data['cases']:
        before,after = rows[case['name'],'before'],rows[case['name'],'after']
        numeric = lambda row: {k for k,v in row.items() if isinstance(v,(int,float)) and not isinstance(v,bool) and k != 'bars'}
        names = numeric(before[0]); check(all(numeric(r) == names for r in before+after), 'Heap metric shape')
        metrics = {}
        for name in sorted(names):
            b = [r[name] for r in before]; a = [r[name] for r in after]; bm,am = statistics.median(b),statistics.median(a)
            metrics[name] = {'beforeSamples':b,'afterSamples':a,'beforeMedian':bm,'afterMedian':am,'afterBeforeRatio':am/bm if bm else None}; metric_count += 1
        summary[case['name']] = {'bars':case['bars'],'mode':case['mode'],'metrics':metrics}
    check(summary == data['summary'], 'Benchmark independent complete medians disagree')
    return {'status':'passed','cases':30,'freshProcesses':180,'repetitionsPerVersion':3,'independentlyRecomputedMetrics':metric_count,'summary':summary,'immutableSummary':str(immutable),'summarySha256':sha(immutable)}

def gates():
    result = {}
    for tag in ('windows','linux'):
        path = D/f'gate-{tag}.log'; log = text(path)
        check(int(text(D/f'gate-{tag}.exit').strip()) == 0, 'Gate exit '+tag)
        rust = re.findall(r'test result: ok\. (\d+) passed; (\d+) failed;',log)
        count = sum(int(a) for a,b in rust); failed = sum(int(b) for a,b in rust)
        check(count == 7327 and failed == 0 and 'test result: FAILED.' not in log, 'Full Rust test count/status '+tag+': '+str((count,failed)))
        python = re.findall(r'\b(\d+) passed\b',log)
        # Pytest has a distinctive all-equals summary; Rust result lines differ.
        pytest = re.findall(r'=+\s*(\d+) passed(?:,\s*\d+ (?:skipped|warnings?))*\s+in\s',log)
        check(pytest and int(pytest[-1]) == 785, 'Python gate count '+tag)
        tools = re.findall(r'Ran (\d+) tests? in',log)
        check(sum(map(int,tools)) == 166, 'Tool test count '+tag+': '+str(tools))
        check('2151 passed; 0 failed;' in log and 'Structural guardrail passed: checked 399 production Rust source files.' in log, 'Runtime/source production suite '+tag)
        skipped = sum(map(int,re.findall(r'OK \(skipped=(\d+)\)',log)))
        check(skipped == (0 if tag == 'windows' else 1), 'Platform tool skip count '+tag)
        result[tag] = {'exit':0,'rustPassed':count,'pythonPassed':785,'toolTestsRun':166,'toolsPassed':166-skipped,'toolsSkipped':skipped,'productionRustFilesChecked':399,'logSha256':sha(path),'exitSha256':sha(D/f'gate-{tag}.exit')}
    targeted = text(D/'targeted-runtime.log')
    check(int(text(D/'targeted-runtime.exit').strip()) == 0 and 'test result: ok. 2151 passed; 0 failed;' in targeted, 'Targeted runtime pass')
    check(int(text(D/'targeted-runtime-attempt1.exit').strip()) != 0 and '1 failed;' in text(D/'targeted-runtime-attempt1.log'), 'First fixture failure receipt was lost')
    check(int(text(D/'build-release.exit').strip()) == 0, 'Release build exit')
    result['targeted'] = {'runtimePassed':2151,'logSha256':sha(D/'targeted-runtime.log'),'firstAttemptLogSha256':sha(D/'targeted-runtime-attempt1.log'),'firstAttemptExit':int(text(D/'targeted-runtime-attempt1.exit').strip())}
    return result

def iteration_isolation():
    archive_path = D/'superseded-first-recovery.json'; archive = load(archive_path)
    check(archive['status'] == 'archived', 'Superseded first recovery status')
    for original, entry in archive['files'].items():
        check(sha(entry['archive']) == entry['sha256'], 'Superseded archive hash '+original)
    archived = lambda name: Path(archive['files'][str(D/name)]['archive'])
    first_audit = load(archived('audit-results.json'))
    check(first_audit['status'] == 'passed', 'Superseded first recovery was not fully audited')
    initial_source = load(archived('after-source-identity.json'))
    final_source = load(D/'after-source-identity.json')
    check(len(initial_source['files']) == len(final_source['files']) == 6310 and initial_source['files'].keys() == final_source['files'].keys(), 'Final and superseded source scope')
    different = [name for name in final_source['files'] if final_source['files'][name] != initial_source['files'][name]]
    check(different == ['crates/pine-runtime/src/algorithms/rolling_window.rs'], 'Unexpected final constant-proof source changes '+str(different))
    check(sha(D/'after-source-identity.json') != sha(archived('after-source-identity.json')), 'Final frozen source is still superseded source')
    for probe in ('heap','differential'):
        first,final = load(archived(f'identity-{probe}-after.json')),load(D/f'identity-{probe}-after.json')
        check(first['executableSha256'] != final['executableSha256'], 'After probe not freshly linked '+probe)
        check(first['libraryHashes']['target/release/libpine_runtime.rlib'] != final['libraryHashes']['target/release/libpine_runtime.rlib'], 'After runtime library still superseded')
    for probe in ('heap','dispatch','result','differential'):
        check(load(D/f'identity-{probe}-before.json') == first_audit['sections']['identities'][probe+'-before']['link'], 'Original before baseline changed '+probe)
    final_count = initial_count = 0
    for filename,run_field in [('ordinary-results.json','after'),('math-results-both.json','run'),('benchmark-results.json','run')]:
        first,final = load(archived(filename)),load(D/filename)
        expected = {'ordinary-results.json':412,'math-results-both.json':132,'benchmark-results.json':180}[filename]
        check(len(first['records']) == len(final['records']) == expected, 'Separated process denominator '+filename)
        first_raw = {row[run_field]['stdout'] for row in first['records']}
        final_raw = {row[run_field]['stdout'] for row in final['records']}
        check(len(first_raw) == len(final_raw) == expected and not first_raw.intersection(final_raw), 'Final receipts reused superseded process output '+filename)
        final_count += len(final['records']); initial_count += len(first['records'])
    check(final_count == initial_count == 724, 'Native final/superseded denominator')
    return {'status':'passed','finalNativeProcesses':724,'finalPriorOrdinaryRawComparisons':412,'supersededNativeProcesses':724,
            'supersededExcludedFromFinalProcessDenominator':True,'newProbeOrBuildExecutionsForThisAudit':0,'sourceFilesChangedSinceSuperseded':different,
            'finalAfterSourceIdentitySha256':sha(D/'after-source-identity.json'),'supersededAfterSourceIdentitySha256':sha(archived('after-source-identity.json')),
            'archiveIdentity':str(archive_path),'archiveIdentitySha256':sha(archive_path),'archivedFilesVerified':len(archive['files']),
            'supersededAudit':str(archived('audit-results.json')),'supersededAuditSha256':sha(archived('audit-results.json'))}

def wasm():
    check(int(text(D/'wasm-numeric-tail.exit').strip()) == 0, 'Real WASM exit')
    result = load(D/'wasm-numeric-tail.stdout')
    check(result['status'] == 'passed' and result['realWasm'] is True and len(result['cases']) == 3, 'Real WASM case count/status')
    check({r['name'] for r in result['cases']} == {'constant-extreme','offset-257','weighted-cancellation'}, 'Real WASM case plan')
    for row in result['cases']:
        check(sha(row['output']) == row['outputSha256'] and row['bars'] == 520, 'WASM raw output SHA/bars')
        data = load(row['output']); check(data['diagnostics'] == [] and all(len(p['values']) == 520 for p in data['plots']), 'WASM diagnostics/shape')
        if row['name'] == 'constant-extreme':
            check({p['title'] for p in data['plots']} == {'wma','hma'}, 'WASM weighted titles')
            for p in data['plots']: check(p['values'][0] is None and all(float_or_na(v) == 1e308 for v in p['values'][1:]), 'WASM exact constant extreme')
        elif row['name'] == 'offset-257':
            check({p['title'] for p in data['plots']} == {'corr','cov'}, 'WASM paired titles')
            for p in data['plots']:
                check(all(v is None for v in p['values'][:256]), 'WASM covariance warmup')
                expected = 1 if p['title'] == 'corr' else 5504
                check(all(v is not None and abs(float_or_na(v)-expected) <= 1e-10 for v in p['values'][256:]), 'WASM paired independent expected')
        else:
            check(len(data['plots']) == 1 and data['plots'][0]['title'] == 'wma', 'WASM cancellation shape')
            check(all(v is not None and abs(float_or_na(v)-.4) <= math.ulp(1.0) for v in data['plots'][0]['values'][3::4]), 'WASM exact cancellation expected')
    identity_path = D/'wasm-bindings-identity.json'; identity = load(identity_path)
    check(identity['status'] == 'passed', 'WASM conversion identity status')
    fields = ('inputWasm','generatedWasm','generatedJavaScript','frozenSourceIdentity','invocationScript','generatorSource','generationLog','testScript','testStdout','testStderr','testExit')
    for field in fields:
        check(sha(identity[field]['path']) == identity[field]['sha256'], 'WASM pipeline identity '+field)
    check(identity['frozenSourceIdentity']['sha256'] == sha(D/'after-source-identity.json'), 'WASM frozen source identity')
    generator = ROOT/'crates/pine-wasm/examples/generate_node_bindings.rs'
    check(identity['generatorSource']['sha256'] == load(D/'after-source-identity.json')['files'][generator.relative_to(ROOT).as_posix()], 'Frozen WASM generator identity')
    expected_generator = ['cargo','run','--quiet','-p','pine-wasm','--example','generate_node_bindings','--target','x86_64-pc-windows-msvc','--','target/wasm32-unknown-unknown/debug/pine_wasm.wasm','.local/numeric-tail-20261004/wasm-bindings']
    check(identity['generatorCommand'] == expected_generator, 'WASM conversion arguments')
    check(identity['nodeCommand'][1:] == ['.local/numeric-tail-20261004/wasm_numeric_tail.cjs','.local/numeric-tail-20261004/wasm-bindings/pine_wasm.js'], 'WASM Node arguments')
    check('pine_wasm_bg.wasm' in text(identity['generatedJavaScript']['path']), 'Node binding must reference generated BG module')
    check(Path(identity['inputWasm']['path']).read_bytes().startswith(b'\0asm') and Path(identity['generatedWasm']['path']).read_bytes().startswith(b'\0asm'), 'WASM module signatures')
    check(identity['launchAttempts'][-1]['nodeExecuted'] is True and identity['launchAttempts'][-1]['exit'] == 0, 'Final numeric Node launch status')
    return {'status':'passed','cases':3,'barsPerCase':520,'stdoutSha256':sha(D/'wasm-numeric-tail.stdout'),'stderrSha256':sha(D/'wasm-numeric-tail.stderr'),
            'scriptSha256':sha(D/'wasm_numeric_tail.cjs'),'pipelineIdentity':str(identity_path),'pipelineIdentitySha256':sha(identity_path),
            'inputWasmSha256':identity['inputWasm']['sha256'],'generatedWasmSha256':identity['generatedWasm']['sha256'],'generatedJavaScriptSha256':identity['generatedJavaScript']['sha256'],
            'limitation':'wasm-bindgen converts the Cargo input; distinct input/BG/JS identities are checked, never assumed to have equal bytes'}

def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--partial',action='store_true')
    args = ap.parse_args()
    output = {'status':'running','readOnly':True,'probeProcessesStarted':0,'buildProcessesStarted':0,'auditorSha256':sha(__file__),'timestampUtc':datetime.now(timezone.utc).isoformat(),
              'auditorCorrections':['399 denotes production Rust files checked by the structural guardrail, not a Rust test count.','wasm-bindgen converts Cargo WASM to generated BG; input and output module identities are separately checked.','Integral JSON number tokens are converted to f64 before applying the WASM Number contract.'],
              'sections':{},'errors':[],'pending':[]}
    identities = None
    tasks = [('beforeSource',lambda:frozen_sources('before')),('afterSource',lambda:frozen_sources('after')),('identities',probe_identities),('gates',gates),('wasm',wasm),
             ('ordinary',lambda:ordinary(identities)),('math',lambda:mathematics(identities)),('benchmark',lambda:benchmark(identities))]
    if (D/'superseded-first-recovery.json').exists(): tasks.append(('iterationIsolation',iteration_isolation))
    for name, task in tasks:
        try:
            value = task(); output['sections'][name] = value
            if name == 'identities': identities = value
            print('PASS',name,flush=True)
        except FileNotFoundError as error:
            item = {'section':name,'error':str(error)}
            (output['pending'] if args.partial else output['errors']).append(item)
            print('PENDING' if args.partial else 'FAIL',name,str(error),flush=True)
        except Exception as error:
            output['errors'].append({'section':name,'error':repr(error)})
            print('FAIL',name,repr(error),flush=True)
    output['status'] = 'failed' if output['errors'] else ('partial' if output['pending'] else 'passed')
    filename = 'audit-partial-results.json' if args.partial else 'audit-results.json'
    (D/filename).write_text(json.dumps(output,indent=2,ensure_ascii=False,allow_nan=False),encoding='utf8')
    check(output['status'] != 'failed', 'Independent audit failed; raw failures retained in '+filename)
    print(output['status'].upper(),flush=True)

if __name__ == '__main__': main()

