use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
use std::time::Instant;
use pine_runtime::{Bar, BarUpdate, HistoricalRuntime, RealtimeRuntime, OutputRetention};
use pine_sema::analyze_source;
use pine_syntax::{SourceFile, Severity};
use serde_json::json;

struct CountingAllocator;
static LIVE: AtomicUsize = AtomicUsize::new(0);
static ALLOCATED: AtomicUsize = AtomicUsize::new(0);
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let p = unsafe { System.alloc(layout) };
        if !p.is_null() { LIVE.fetch_add(layout.size(), Relaxed); ALLOCATED.fetch_add(layout.size(), Relaxed); ALLOCS.fetch_add(1, Relaxed); }
        p
    }
    unsafe fn dealloc(&self, p: *mut u8, layout: Layout) {
        LIVE.fetch_sub(layout.size(), Relaxed);
        unsafe { System.dealloc(p, layout) }
    }
    unsafe fn realloc(&self, p: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        let q = unsafe { System.realloc(p, layout, size) };
        if !q.is_null() { LIVE.fetch_add(size, Relaxed); LIVE.fetch_sub(layout.size(), Relaxed); ALLOCATED.fetch_add(size, Relaxed); ALLOCS.fetch_add(1, Relaxed); }
        q
    }
}
#[global_allocator] static GLOBAL: CountingAllocator = CountingAllocator;
fn bar(i: usize) -> Bar { let x=100.0+(i%17) as f64/16.0; Bar {time:1700000000+i as i64*60,open:x, high:x+1.0,low:x-1.0,close:x+0.25,volume:100.0} }
fn median(v: &mut [f64]) -> f64 {v.sort_by(f64::total_cmp); v[v.len()/2]}
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    let source_text = std::fs::read_to_string(&args[1])?;
    let n: usize = args[2].parse()?;
    let mode=args.get(3).map(String::as_str).unwrap_or("historical");
    let source=SourceFile::new("probe.pine",source_text);
    let analysis=analyze_source(&source);
    if analysis.diagnostics.iter().any(|d|d.severity==Severity::Error) {return Err(format!("{:?}", analysis.diagnostics).into());}
    let hir=analysis.hir.ok_or("no hir")?;
    let initial=LIVE.load(Relaxed);
    if mode=="historical" {
        let mut runtime=HistoricalRuntime::new(&hir);
        let initial_allocated=ALLOCATED.load(Relaxed);
        let initial_allocations=ALLOCS.load(Relaxed);
        let started=Instant::now();
        for i in 0..n {runtime.append_bar(bar(i)).map_err(|e|e.message)?;}
        let seed_ms=started.elapsed().as_secs_f64()*1000.0;
        let seed_allocated=ALLOCATED.load(Relaxed)-initial_allocated;
        let seed_allocations=ALLOCS.load(Relaxed)-initial_allocations;
        let retained=LIVE.load(Relaxed)-initial;
        let profile=runtime.profile();
        let mut times=[0.0;31]; let mut clone_bytes=0; let mut clone_allocs=0;
        for t in &mut times {let live=LIVE.load(Relaxed); let count=ALLOCS.load(Relaxed); let started=Instant::now(); let copy=std::hint::black_box(runtime.clone()); *t=started.elapsed().as_secs_f64()*1000.0; clone_bytes=LIVE.load(Relaxed)-live;clone_allocs=ALLOCS.load(Relaxed)-count;drop(copy);}
        let live=LIVE.load(Relaxed); let started=Instant::now(); let result=runtime.result(); let result_ms=started.elapsed().as_secs_f64()*1000.0; let result_bytes=LIVE.load(Relaxed)-live;
        println!("{}",json!({"mode":mode,"bars":n,"script":args[1],"retainedHeapBytes":retained,"seedMs":seed_ms,"seedAllocatedBytes":seed_allocated,"seedAllocations":seed_allocations,"rollingWindowValues":profile.rolling_window_values,"rollingWindowValueCapacity":profile.rolling_window_value_capacity,"seriesValues":profile.series_values,"matrixSlots":profile.matrix_slots,"matrixCells":profile.matrix_cells,"arraySlots":profile.array_slots,"arrayValues":profile.array_values,"cloneHeapBytes":clone_bytes,"cloneAllocations":clone_allocs,"cloneMedianMs":median(&mut times),"resultHeapBytes":result_bytes,"resultMs":result_ms,"plotValues":profile.plot_values}));
        std::hint::black_box(result);
    } else {
        let mut runtime=RealtimeRuntime::new(&hir);
        if mode=="retained" {runtime.set_output_retention(OutputRetention::keep_confirmed_bars(64));}
        let bars:Vec<_>=(0..n).map(bar).collect();
        drop(runtime.seed_historical(&bars).map_err(|e|e.message)?);drop(bars);
        let retained=LIVE.load(Relaxed)-initial;
        let mut diff_ms=[0.0;31]; let mut diff_bytes=[0usize;31];
        let mut full_ms=[0.0;31]; let mut full_bytes=[0usize;31];
        for i in 0..31 {
            let prior=ALLOCATED.load(Relaxed);let start=Instant::now();let changes=runtime.apply_update(BarUpdate::forming(bar(n))).map_err(|e|e.message)?; diff_ms[i]=start.elapsed().as_secs_f64()*1000.0;diff_bytes[i]=ALLOCATED.load(Relaxed)-prior;drop(changes);
            let prior=ALLOCATED.load(Relaxed);let start=Instant::now();let result=runtime.update(BarUpdate::forming(bar(n))).map_err(|e|e.message)?;full_ms[i]=start.elapsed().as_secs_f64()*1000.0;full_bytes[i]=ALLOCATED.load(Relaxed)-prior;drop(result);
        }
        diff_bytes.sort();full_bytes.sort();
        println!("{}",json!({"mode":mode,"bars":n,"script":args[1],"retainedHeapBytes":retained,"applyUpdateMedianMs":median(&mut diff_ms),"updateMedianMs":median(&mut full_ms),"applyAllocatedMedianBytes":diff_bytes[15],"updateAllocatedMedianBytes":full_bytes[15],"seriesValues":runtime.profile().series_values,"matrixSlots":runtime.profile().matrix_slots}));
    }
    Ok(())
}

independent_math.py.source:
"""Independent Fraction oracles of representable inputs, with explicit numerical scope.

Expected covariance uses exact population centered products. Weighted means use
exact integer weights of input f64 values. HMA rounds each finite weighted stage
to f64, computes the finite mathematical difference, and propagates a genuinely
out-of-range stage as NA. Mixed-scale normalization underflow is an explicitly
unqualified diagnostic. No production helper supplies an expected value.
"""
from __future__ import annotations
import argparse
from fractions import Fraction
import math
from pathlib import Path
import struct
from evidence_common import D, ROOT, sha, save, identity, directory, execute, snapshots, finite, source

OFFSETS = (.5, -.5, .25, -.25)

def specs():
    rows = []
    for length in (127, 257, 511, 512):
        for offset, right in ((1e8, 2e8), (-1e12, 2e12)):
            rows.append({'name': f'paired_{length}_{offset:g}', 'kind': 'paired', 'length': length,
                         'offset': offset, 'rightOffset': right, 'seed': 2*length+3})
    rows += [dict(name='identity_37_1e8', kind='identity', length=37, offset=1e8, seed=77),
             dict(name='inverse_257_1e15', kind='inverse', length=257, offset=1e15, seed=517)]
    for length in (2, 3, 16, 257, 512, 5000):
        for sign in (1, -1):
            rows.append({'name': f'constant_{sign}_{length}', 'kind': 'weighted', 'pattern': 'constant',
                         'length': length, 'value': sign*1e308, 'seed': max(17, length+round(math.sqrt(length))+4),
                         'constantExact': True})
    rows += [dict(name='constant_max_2', kind='weighted', pattern='constant', length=2, value=float.fromhex('0x1.fffffffffffffp+1023'), seed=17, constantExact=True),
             dict(name='constant_negative_max_16', kind='weighted', pattern='constant', length=16, value=-float.fromhex('0x1.fffffffffffffp+1023'), seed=25, constantExact=True),
             dict(name='constant_1e200_257', kind='weighted', pattern='constant', length=257, value=1e200, seed=278),
             dict(name='constant_subnormal_16', kind='weighted', pattern='constant', length=16, value=1e-310, seed=25),
             dict(name='mixed_cancellation_4', kind='weighted', pattern='cancellation', length=4, seed=17),
             dict(name='overflow_tail_2', kind='weighted', pattern='tail', length=2, seed=4),
             dict(name='na_tail_16', kind='weighted', pattern='na-tail', length=16, seed=20),
             dict(name='forming_sign_2', kind='weighted', pattern='forming', length=2, seed=17),
             dict(name='genuine_stage_overflow_2', kind='weighted', pattern='stage-overflow', length=2, seed=17),
             dict(name='unqualified_mixed_scale_2', kind='weighted', pattern='mixed-scale', length=2, seed=17,
                  unqualified='Normalizing 1e308 and 1e-308 loses the tiny input; mathematical target is diagnostic only'),
             dict(name='unqualified_third_component_5', kind='weighted', pattern='third-component', length=5, seed=17,
                  unqualified='Separated normalized sum residuals may require a third expansion component; mathematical target is diagnostic only')]
    return rows

def pine(spec):
    length = spec['length']
    if spec['kind'] in ('paired', 'identity', 'inverse'):
        x = f"{spec['offset']!r} + bar_index % {length}"
        if spec['kind'] == 'paired':
            y = f"{spec['rightOffset']!r} + (bar_index * 2) % {length}"
        else:
            y = '-x' if spec['kind'] == 'inverse' else 'x'
        body = f'x = {x}\ny = {y}\nplot(x, "x")\nplot(y, "y")\nplot(ta.correlation(x, y, {length}), "corr")\nplot(ta.covariance(x, y, {length}), "cov")\n'
    else:
        pattern = spec['pattern']
        expressions = {'constant': f"{spec.get('value', 0)!r} + bar_index * 0.0",
                       'cancellation': 'bar_index % 4 == 2 ? -1e308 : (bar_index % 4 == 3 ? 1.0 : 1e308)',
                       'tail': 'bar_index < 2 ? 1e308 : 1.0',
                       'na-tail': 'bar_index < 2 ? 1e308 : (bar_index == 2 ? na : 1.0)',
                       'forming': 'close > 100.5 ? 1e308 : -1e308',
                       'stage-overflow': 'bar_index % 2 == 0 ? -1e308 : 1.5e308',
                       'mixed-scale': 'bar_index % 2 == 0 ? 1e308 : 1e-308',
                       'third-component': 'bar_index % 5 == 2 ? math.pow(2.0, 923.0) : (bar_index % 5 == 3 ? 1.0 : (bar_index % 5 == 4 ? -1e308 : 1e308))'}
        body = f'x = {expressions[pattern]}\nplot(x, "x")\nplot(ta.wma(x, {length}), "wma")\nplot(ta.hma(x, {length}), "hma")\n'
    return f'//@version=6\nindicator("Independent {spec["name"]}")\n' + body

def inputs(spec, index, close):
    length = spec['length']
    if spec['kind'] in ('paired', 'identity', 'inverse'):
        x = float(spec['offset'] + index % length)
        y = float(spec['rightOffset'] + (index*2) % length) if spec['kind'] == 'paired' else (-x if spec['kind'] == 'inverse' else x)
        return {'x': x, 'y': y}
    pattern = spec['pattern']
    if pattern == 'constant': x = spec['value']
    elif pattern == 'cancellation': x = -1e308 if index%4 == 2 else (1.0 if index%4 == 3 else 1e308)
    elif pattern == 'tail': x = 1e308 if index < 2 else 1.0
    elif pattern == 'na-tail': x = 1e308 if index < 2 else (None if index == 2 else 1.0)
    elif pattern == 'forming': x = 1e308 if close > 100.5 else -1e308
    elif pattern == 'stage-overflow': x = -1e308 if index%2 == 0 else 1.5e308
    elif pattern == 'mixed-scale': x = 1e308 if index%2 == 0 else 1e-308
    elif pattern == 'third-component': x = (1e308,1e308,2.0**923,1.0,-1e308)[index%5]
    else: raise ValueError(pattern)
    return {'x': x}

def as_finite(value):
    try: result = float(value)
    except OverflowError: return None
    return result if math.isfinite(result) else None

def weighted(values):
    if not values or any(value is None for value in values):
        return None
    if all(value == values[0] for value in values):
        return values[0]
    numerator = sum((Fraction.from_float(value)*weight for weight,value in enumerate(values, 1)), Fraction())
    return as_finite(numerator / (len(values)*(len(values)+1)//2))

def target(spec, index, sample, cache):
    length = spec['length']
    smooth = round(math.sqrt(length))
    start = max(0, index-length-smooth+2) if spec['kind'] == 'weighted' else max(0, index-length+1)
    # Static inputs use a bar-index key. Only forming_sign depends on prices.
    dynamic = spec.get('pattern') == 'forming'
    key = (spec['name'], index, tuple(sample[i]['x'] for i in range(start,index+1)) if dynamic else ())
    if key in cache: return cache[key]
    expected = {}
    if spec['kind'] != 'weighted':
        expected = {'corr': None, 'cov': None}
        if index+1 >= length:
            a = [Fraction.from_float(sample[i]['x']) for i in range(index-length+1,index+1)]
            b = [Fraction.from_float(sample[i]['y']) for i in range(index-length+1,index+1)]
            ma,mb = sum(a)/length,sum(b)/length
            cov = sum((x-ma)*(y-mb) for x,y in zip(a,b))/length
            va = sum((x-ma)**2 for x in a)/length
            vb = sum((y-mb)**2 for y in b)/length
            expected['cov'] = as_finite(cov)
            if va and vb:
                expected['corr'] = math.copysign(math.sqrt(float(cov*cov/(va*vb))), -1 if cov < 0 else 1)
    else:
        values = [sample[i]['x'] for i in range(max(0,index-length+1),index+1)]
        expected['wma'] = weighted(values) if index+1 >= length else None
        diffs = []
        if index+1 >= length+smooth-1:
            for end in range(index-smooth+1,index+1):
                window = [sample[i]['x'] for i in range(end-length+1,end+1)]
                full = weighted(window)
                half = weighted(window[-max(1,length//2):])
                diff = None if full is None or half is None else as_finite(2*Fraction.from_float(half)-Fraction.from_float(full))
                diffs.append(diff)
        expected['hma'] = weighted(diffs) if diffs else None
    cache[key] = expected
    return expected

def matched(actual, expected):
    actual = finite(actual)
    if expected is None: return actual is None
    if actual is None: return False
    tolerance = max(abs(expected)*2e-12, 8*math.ulp(expected))
    return abs(actual-expected) <= tolerance

def analyze(spec, mode, raw, cache):
    records = snapshots(raw)
    seed = spec['seed']
    confirmed = [100.0+(i%17)/16.0+.25 for i in range(seed)]
    failures = []
    mismatches = 0
    checked = exact_constant = actual_na = expected_na = 0
    for ri, record in enumerate(records):
        if ri == 0:
            closes = list(confirmed)
        else:
            i = seed+(ri-1)//4
            closes = confirmed + [100.0+(i%17)/16.0+OFFSETS[(ri-1)%4]]
        samples = [inputs(spec,i,close) for i,close in enumerate(closes)]
        plots = record['snapshot']['plots']
        values = {p['title']: p['values'] for p in plots}
        titles = {'x','wma','hma'} if spec['kind'] == 'weighted' else {'x','y','corr','cov'}
        if len(values) != len(plots) or set(values) != titles:
            raise ValueError('Unexpected or duplicate plot titles')
        count = len(next(iter(values.values())))
        if any(len(v) != count for v in values.values()): raise ValueError('Mismatched plot lengths')
        if mode == 'unlimited':
            expected_count = len(closes)
        elif ri == 0:
            expected_count = min(seed, 16)
        elif (ri-1)%4 < 3:
            expected_count = min(len(closes)-1, 16)+1
        else:
            expected_count = min(len(closes), 16)
        if count != expected_count:
            raise ValueError(f'Unexpected {mode} output count at snapshot {ri}: {count} != {expected_count}')
        first = len(closes)-count
        if first < 0:
            raise ValueError('Unexpected retention output shape')
        for j in range(count):
            index = first+j
            for name,value in samples[index].items():
                actual = finite(values[name][j])
                if actual != value:
                    raise ValueError(f'Declared input float differs at {index}/{name}: {actual} != {value}')
            expected = target(spec,index,samples,cache)
            for name,value in expected.items():
                actual = finite(values[name][j])
                checked += 1
                actual_na += actual is None
                expected_na += value is None
                match = matched(actual,value)
                if spec.get('constantExact') and value is not None:
                    match = actual is not None and struct.pack('>d',actual) == struct.pack('>d',spec['value'])
                    exact_constant += 1
                if not match:
                    mismatches += 1
                    if len(failures) < 24:
                        failures.append({'snapshotIndex':ri,'barIndex':index,'plot':name,'actual':actual,'independentExpected':value})
        if ri > 0 and (ri-1)%4 == 3:
            confirmed = closes
    if checked <= 0:
        raise ValueError('No aggregate values were independently checked')
    return {'checkedAggregateValues': checked, 'mismatchValues': mismatches,
            'exactConstantValues': exact_constant, 'firstMismatches': failures,
            'actualNaAggregateValues': actual_na, 'expectedNaAggregateValues': expected_na,
            'independentMathPassed': mismatches == 0 and not spec.get('unqualified'),
            'unqualifiedReason': spec.get('unqualified'), 'snapshots':33,'changes':32}

def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--prepare-only', action='store_true')
    ap.add_argument('--tag', choices=('before','after','both'), default='both')
    ap.add_argument('--timeout', type=float, default=180)
    args = ap.parse_args()
    cases = specs()
    sources = {s['name']: source(D/'math-inputs'/(s['name']+'.pine'), pine(s)) for s in cases}
    if args.prepare_only:
        save(D/'math-plan.json',{'specs':cases,'sources':sources,'publicCases':len(cases)*2,
             'plannedProcessesBothVersions':len(cases)*4,'qualifiedPublicCases':2*sum(not s.get('unqualified') for s in cases),
             'unqualifiedPublicCases':2*sum(bool(s.get('unqualified')) for s in cases),'probesExecuted':False})
        print(f'Prepared {len(cases)} sources / {len(cases)*2} public cases / {len(cases)*4} processes.',flush=True)
        return
    tags = ('before','after') if args.tag == 'both' else (args.tag,)
    identities = {tag:identity('differential',tag) for tag in tags}
    out = directory('math')
    receipt = {'status':'running','specs':cases,'sources':sources,'identities':identities,
               'runnerSha256':sha(Path(__file__)),'commonSha256':sha(D/'evidence_common.py'),
               'oracle':'Fraction.from_float input f64; exact centered population moments; exact integer weighted sums and finite rounded HMA stages',
               'tolerance':'2e-12 relative or 8 ULP; only constantExact cases require exact source f64 bits',
               'scope':'Only these explicit inputs; mixed-scale normalization-underflow diagnostic is excluded from mathematical qualification',
               'plannedProcesses':len(cases)*2*len(tags),'records':[]}
    cache = {}
    try:
        for spec in cases:
            for mode in ('unlimited','retained'):
                for tag in tags:
                    run,raw=execute(out,spec['name']+'-'+mode+'-'+tag,
                         [identities[tag]['binary'],sources[spec['name']]['path'],mode,str(spec['seed'])],args.timeout)
                    row={'case':spec['name'],'tag':tag,'mode':mode,'seedBars':spec['seed'],'run':run}
                    receipt['records'].append(row)
                    save(out/'progress.json',receipt)
                    if run['returncode'] != 0: raise RuntimeError('Math probe process failed: '+spec['name'])
                    row['analysis']=analyze(spec,mode,raw,cache)
                    save(out/'progress.json',receipt)
                    print(spec['name'],mode,tag,'mismatches',row['analysis']['mismatchValues'],flush=True)
        for tag in tags:
            if identity('differential',tag) != identities[tag]: raise ValueError('Probe identity changed')
        for entry in sources.values():
            if sha(Path(entry['path'])) != entry['sha256']: raise ValueError('Math input changed')
        failures=[r for r in receipt['records'] if r['tag']=='after' and not r['analysis']['unqualifiedReason'] and not r['analysis']['independentMathPassed']]
        status = 'diagnostic_complete' if args.tag == 'before' else ('passed' if not failures else 'failed')
        receipt.update(status=status,completedProcesses=len(receipt['records']),
                       failedAfterProcesses=len(failures),afterMathFailures=failures,
                       qualifiedProcesses={tag:sum(r['tag']==tag and not r['analysis']['unqualifiedReason'] for r in receipt['records']) for tag in tags},
                       mathPassedProcesses={tag:sum(r['tag']==tag and r['analysis']['independentMathPassed'] for r in receipt['records']) for tag in tags},
                       unqualifiedProcesses=sum(bool(r['analysis']['unqualifiedReason']) for r in receipt['records']))
        save(out/'summary.json',receipt)
        save(D/('math-results-'+args.tag+'.json'),receipt)
        if failures: raise RuntimeError(f'{len(failures)} after math processes failed; all receipts retained')
        if args.tag == 'before':
            print('COMPLETE before diagnostics; mathematical mismatches and unqualified diagnostics retained; no after process executed',flush=True)
        else:
            print('PASS qualified after math; before mismatches and unqualified diagnostics retained',flush=True)
    except BaseException as error:
        receipt.update(status='failed',error=repr(error),completedProcesses=len(receipt['records']))
        save(out/'failure.json',receipt)
        save(out/'progress.json',receipt)
        raise

if __name__=='__main__':
    main()

